#!/usr/bin/env python3
"""Emit /results/sentinel.json from live SENTINEL state."""
import json
import socket

SENTINEL_PORTS = [26379, 26380, 26381]
MASTER_NAME = "shop-master"


def cmd(port, *args):
    """Minimal RESP client: send one command, return decoded reply."""
    payload = f"*{len(args)}\r\n".encode()
    for a in args:
        a = str(a).encode()
        payload += b"$%d\r\n%s\r\n" % (len(a), a)
    with socket.create_connection(("127.0.0.1", port), timeout=5) as s:
        s.sendall(payload)
        buf = b""
        while True:
            chunk = s.recv(65536)
            if not chunk:
                break
            buf += chunk
            try:
                val, rest = parse(buf)
            except (IndexError, ValueError):
                continue
            return val
    raise RuntimeError("no reply")


def parse(b):
    t, line, rest = b[0:1], *b[1:].split(b"\r\n", 1)
    if t in b"+-:":
        return (line.decode(), rest)
    if t == b"$":
        n = int(line)
        if n == -1:
            return (None, rest)
        return (rest[:n].decode(), rest[n + 2:])
    if t == b"*":
        n = int(line)
        out = []
        for _ in range(n):
            v, rest = parse(rest)
            out.append(v)
        return (out, rest)
    raise ValueError("bad type")


# Cross-check every sentinel agrees on the master address.
addrs = {p: cmd(p, "SENTINEL", "get-master-addr-by-name", MASTER_NAME) for p in SENTINEL_PORTS}
for p, a in addrs.items():
    print(f"sentinel {p}: get-master-addr-by-name -> {a}")
assert len({tuple(a) for a in addrs.values()}) == 1, f"sentinels disagree: {addrs}"
master_addr = [str(x) for x in addrs[SENTINEL_PORTS[0]]]
assert master_addr == ["127.0.0.1", "6379"], master_addr

flat = cmd(SENTINEL_PORTS[0], "SENTINEL", "master", MASTER_NAME)
info = dict(zip(flat[::2], flat[1::2]))
num_other = int(info["num-other-sentinels"])
num_slaves = int(info["num-slaves"])
print(f"num-other-sentinels={num_other} num-slaves={num_slaves} flags={info['flags']}")
assert num_other >= 2, num_other
assert num_slaves >= 2, num_slaves

doc = {
    "master_name": MASTER_NAME,
    "master_addr": master_addr,
    "num_other_sentinels": num_other,
    "num_slaves": num_slaves,
    "sentinels": sorted(SENTINEL_PORTS),
}
with open("/results/sentinel.json", "w", encoding="utf-8") as f:
    json.dump(doc, f, indent=2)
    f.write("\n")
print("wrote /results/sentinel.json")

